import {DAY,dayTime,isoDay,calendar,atDate,tier,planFor,parseBars,thresholdState} from './engine.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:8}):'—',delta=n=>Number.isFinite(n)?(n>0?'+':'')+fmt(n):'无前值';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let data,assetId='BTC',span=90,asOf,visibleDays=[],hoverIndex=-1,locked=false;
let publishedPrices={assets:{}},referencePrices={assets:{}},priceMode='auto',priceLoadError='';
const priceCache=new Map(),priceNotes=new Map(),priceBusy=new Set();
const sourceLabel=p=>p?.sourceKind==='reference_archive'?'参考站历史':'用户 Notion 原页';
const latestViewDate=()=>[data.dataDate,...Object.values(publishedPrices.assets).map(r=>r.latestDate).filter(Boolean)].sort().at(-1);
function usePublishedPrices(){
 for(const a of data.assets){const direct=publishedPrices.assets[a.id],reference=referencePrices.assets[a.id];const row=priceMode==='reference'?reference:priceMode==='public'?direct:direct?.bars?.length?direct:reference;
  priceCache.set(a.id,row?.bars||[]);
  const warning=direct?.status==='error'?'；公开源本次更新失败：'+direct.error:'';
  priceNotes.set(a.id,row?.bars?.length?(row.label+' · 数据截至 '+row.latestDate+(row.updatedAt?' · 抓取 '+row.updatedAt:' · 归档 '+referencePrices.fetchedAt)+warning+(priceLoadError?'；'+priceLoadError:'')):'此标签暂无已核实公开价格映射或该源无数据；不猜测代码。'+warning+(priceLoadError?'；'+priceLoadError:''));
 }
}
async function refreshPublishedPrices(initial=false){
 const fetchJson=async path=>{const r=await fetch(path,{cache:'no-cache',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('价格文件读取失败 '+r.status);return r.json();};
 const outcomes=await Promise.allSettled([fetchJson('./data/prices.json'),initial?fetchJson('./data/reference-prices.json'):Promise.resolve(referencePrices)]),errors=[];
 for(let i=0;i<outcomes.length;i++){const r=outcomes[i],schema=i?'traderhome_reference_prices_v1':'traderhome_public_prices_v1';if(r.status==='fulfilled'&&r.value.schema===schema){if(i)referencePrices=r.value;else publishedPrices=r.value;}else errors.push((r.reason?.message||'价格版本不符')+'，保留已加载数据及原日期');}priceLoadError=errors.join('；');
 if(initial||priceMode!=='local')usePublishedPrices();
}
const pairMap={BTC:'BTCUSDT',ETH:'ETHUSDT',BNB:'BNBUSDT',SOL:'SOLUSDT',Doge:'DOGEUSDT',LTC:'LTCUSDT',Pepe:'PEPEUSDT',Sui:'SUIUSDT',zec:'ZECUSDT'};
const tierLabel={focus:'优先复核',new:'新周期',avoid:'谨慎 / 回避',watch:'一般观察',missing:'未覆盖'};
const asset=()=>data.assets.find(a=>a.id===assetId);
function renderList(){
 const query=$('search').value.toLowerCase(),filter=$('filter').value;const rank={focus:0,new:1,watch:2,avoid:3,missing:4};
 const items=data.assets.map(a=>({a,p:atDate(a,asOf)})).filter(({a,p})=>a.id.toLowerCase().includes(query)||a.sector.toLowerCase().includes(query)).filter(({p})=>filter==='all'||tier(p)===filter).sort((x,y)=>rank[tier(x.p)]-rank[tier(y.p)]||x.a.id.localeCompare(y.a.id));
 $('count').textContent=items.length+'项';$('assetList').innerHTML=items.map(({a,p})=>`<button class="asset-row ${a.id===assetId?'selected':''}" data-asset="${esc(a.id)}" aria-pressed="${a.id===assetId}"><strong>${esc(a.id)}</strong><span class="${p?.cycle==='进场'?'tone-green':'tone-red'}">${p?fmt(p.otc):'—'}</span><small>${esc(p?.cycle||'未覆盖')} · ${esc(p?.quality||'待定')}</small><small>${tierLabel[tier(p)]}</small></button>`).join('')||'<p class="metadata">无匹配标的。</p>';
}
function renderPlan(viewDate=asOf){
 const a=asset(),p=atDate(a,viewDate),plan=planFor(a,p,viewDate,today());$('planDate').textContent=p?.date===viewDate?viewDate:viewDate+'（最近记录 '+(p?.date||'无')+'）';
 const list=(title,arr)=>`<div class="plan-block"><h3>${title}</h3><ul>${arr.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`;
 $('planBody').innerHTML=`<div class="verdict tone-${plan.tone}">${esc(plan.title)}</div><p class="why">${esc(plan.why)}</p>${list('下一步确认',plan.next)}${list('撤销 / 失效条件',plan.invalid)}${list('目前不能执行的原因',plan.missing)}${p?`<details class="plan-block"><summary>历史评级依据</summary><p>${esc(p.qualityNote||'历史评级依据不足，维持待定。')}</p></details>`:''}`;
 $('assetTitle').textContent=a.id;$('assetMeta').textContent=a.sector+' · '+(p?p.cycle+'第'+p.day+p.unit:'无历史记录');$('quality').textContent='历史质量 · '+(p?.quality||'待定');
 $('metrics').innerHTML=p?[['场外指数',p.otc,p.otcDelta],['爆破指数',p.burst,p.burstDelta],['来源日',p.date,null]].map(([name,n,d])=>`<div class="metric"><span>${name}</span><strong style="${name==='来源日'?'font-size:18px':''}">${typeof n==='number'?fmt(n):esc(n)}</strong>${name==='来源日'?'<small>非实时状态</small>':`<small class="${d>0?'tone-green':d<0?'tone-red':'tone-muted'}">来源Δ ${delta(d)}${p.deltaDays?' · 间隔'+p.deltaDays+'日':''}</small>`}</div>`).join(''):'<p>该日期尚无记录</p>';
 const context=p?.sourceKind==='user_notion'?data.days.find(d=>d.date===p?.date):null;const source=p?.source?`<a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">查看${sourceLabel(p)}</a>`:'历史记录原页链接缺失';
 $('context').innerHTML=`<p>${source} · 数据日 ${esc(p?.date)}。缺失日不会补值。</p><p>资金明细合计 ${fmt(context?.flowSum)} 亿美元；原页总述 ${fmt(context?.flowHeadline)} 亿美元。</p><p class="tone-amber">${esc(context?.flowWarning||'该日资金口径未完整覆盖。')}</p><p>潜力观察：${esc(context?.potential||'该日潜力原文未覆盖')}。价格区间不是止损，需确认标的与交易场所。</p><p>来源复盘（未独立核验）：${esc(context?.review||'未覆盖')}</p><p>风险窗口：退场爆破负转正防反弹，进场跌回200需复评节点。重大事件时点未接入，不代表没有事件风险。</p><p>市场门控：日内大盘不稳时不必操作。<a href="/daily-trade/">结合其他体系与早晚报</a></p>`;
 $('thresholds').innerHTML=p?(thresholdState(p).map(t=>`<span class="threshold-badge ${t.startsWith('场外')?'danger':'warning'}">${t}</span>`).join('')||'<span class="threshold-badge">场外 ≥ 1000 · 爆破 ≥ 200</span>')+'<span class="metadata">'+esc(sourceLabel(p))+' · '+esc(p.date)+'</span>':'<span class="metadata">该日期无场外数据</span>';
 $('events').innerHTML=a.points.filter(p=>p.date<=viewDate&&(p.node||p.transition||p.unconfirmedNode||p.thresholdEvents?.length||p.thresholdCandidates?.length)).slice(-7).reverse().map(p=>`<div class="event"><small>${p.date}</small><span>${esc([...(p.thresholdEvents||[]),...(p.thresholdCandidates||[]).map(t=>t+'（跨缺页/换源待核）'),p.transition?'转'+p.cycle+(p.gapBefore?'（跨缺页）':''):p.node||''].filter(Boolean).join(' · ')||'旧标记待核')}</span><span>${fmt(p.otc)}</span></div>`).join('')||'<p>截至所选日，没有可展示的节点。不能用未来节点回填。</p>';
}
function chartSvg(){
 const a=asset(),end=asOf,start=span?isoDay(Math.max(dayTime(data.startDate),dayTime(end)-(span-1)*DAY)):data.startDate;
 visibleDays=calendar(start,end);const width=Math.max(320,$('chart').clientWidth),height=$('chart').clientHeight,left=46,right=44,plotWidth=width-left-right,step=plotWidth/Math.max(1,visibleDays.length);
 const x=i=>left+(i+.5)*step,points=new Map(a.points.map(p=>[p.date,p])),bars=new Map((priceCache.get(assetId)||[]).map(b=>[b.date,b]));
 const panels=[{key:'price',name:'价格日K',top:25,bottom:height*.32},{key:'otc',name:'场外指数',top:height*.32+34,bottom:height*.68},{key:'burst',name:'爆破指数',top:height*.68+32,bottom:height-33}];
 let out=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(assetId)}价格、场外及爆破日线图"><defs><pattern id="gap" width="6" height="6" patternUnits="userSpaceOnUse"><path d="M0 6L6 0" stroke="#344051" stroke-width=".5"/></pattern></defs>`;
 for(const panel of panels){const isPrice=panel.key==='price';const shown=visibleDays.map(d=>isPrice?bars.get(d):points.get(d)).filter(Boolean);let values=isPrice?shown.flatMap(b=>[b.low,b.high]):shown.map(p=>p[panel.key]);
  if(!isPrice)values.push(...(panel.key==='otc'?[1000]:[0,200]));let min=values.length?Math.min(...values):0,max=values.length?Math.max(...values):1;if(min===max){min-=1;max+=1;}const pad=(max-min)*.1;min-=pad;max+=pad;const y=v=>panel.bottom-(v-min)/(max-min)*(panel.bottom-panel.top);
  out+=`<text class="axis-title" x="${left}" y="${panel.top-9}">${panel.name}${isPrice?' · '+(bars.size?'来源见上方':'未加载'):''}</text>`;
  visibleDays.forEach((d,i)=>{const p=points.get(d);out+=`<rect x="${left+i*step}" y="${panel.top}" width="${step+.1}" height="${panel.bottom-panel.top}" fill="${p?p.cycle==='进场'?'#153728':'#40252f':'url(#gap)'}" opacity="${p?.5:.35}"/>`;});
  for(let j=0;j<3;j++){const v=min+(max-min)*j/2,yy=y(v);out+=`<line x1="${left}" x2="${width-right}" y1="${yy}" y2="${yy}" stroke="#273447" stroke-width=".6"/><text x="${width-right+5}" y="${yy+4}">${fmt(v)}</text>`;}
  if(isPrice){if(!shown.length)out+=`<text x="${width/2}" y="${(panel.top+panel.bottom)/2}" text-anchor="middle">${width<500?'未接入价格，不补造K线':'加载具名公开日K，或导入本地OHLC；数据只在浏览器内存'}</text>`;
   visibleDays.forEach((d,i)=>{const b=bars.get(d);if(!b)return;const color=b.close>=b.open?'#5bd6a0':'#ed7e87',bw=Math.max(1,Math.min(9,step*.62));out+=`<line x1="${x(i)}" x2="${x(i)}" y1="${y(b.high)}" y2="${y(b.low)}" stroke="${color}"/><rect x="${x(i)-bw/2}" y="${Math.min(y(b.open),y(b.close))}" width="${bw}" height="${Math.max(1,Math.abs(y(b.open)-y(b.close)))}" fill="${color}"/>`;});
  }else{
   const threshold=panel.key==='otc'?1000:200,color=panel.key==='otc'?'#ff7889':'#ffc46b';
   out+=`<rect x="${left}" y="${y(threshold)}" width="${plotWidth}" height="${panel.bottom-y(threshold)}" fill="${color}" opacity=".065"/>`;
   for(const level of panel.key==='otc'?[1000]:[0,200])out+=`<line x1="${left}" x2="${width-right}" y1="${y(level)}" y2="${y(level)}" stroke="${color}" stroke-width="${level===threshold?2:1}" stroke-dasharray="7 4"/><text class="threshold-label" x="5" y="${y(level)+4}" style="fill:${color}">${level}</text>`;
   let path='',connected=false;visibleDays.forEach((d,i)=>{const p=points.get(d);if(!p){connected=false;return;}path+=(connected?'L':'M')+x(i)+' '+y(p[panel.key])+' ';connected=true;});
   out+=`<path d="${path}" fill="none" stroke="${panel.key==='otc'?'#66b8ef':'#bb96ef'}" stroke-width="2"/>`;
   visibleDays.forEach((d,i)=>{const p=points.get(d);if(!p)return;const xx=x(i),yy=y(p[panel.key]),label=panel.key==='otc'?'场外跌破1000':'爆破跌破200';if(p[panel.key]<threshold)out+=`<circle cx="${xx}" cy="${yy}" r="${visibleDays.length>150?1.5:2.5}" fill="${color}"/>`;if(p.thresholdEvents?.includes(label))out+=`<path d="M${xx} ${yy-3}l-6-10h12z" fill="${color}" stroke="#0e1725" stroke-width="1.5"><title>${d} ${label}</title></path>`;});
   if(panel.key==='otc')visibleDays.forEach((d,i)=>{const p=points.get(d);if(!p)return;const xx=x(i),yy=y(p.otc);if(p.node||p.transition)out+=`<circle cx="${xx}" cy="${yy}" r="4" fill="${p.transition?p.cycle==='进场'?'#5bd6a0':'#ed7e87':'#f2c272'}"><title>${esc(d+' '+(p.node||'转'+p.cycle))}</title></circle>`;else if(p.unconfirmedNode)out+=`<path d="M${xx} ${yy-5}l5 5-5 5-5-5z" fill="none" stroke="#f2c272"/>`;if(p.approaching)out+=`<path d="M${xx} ${yy-12}l-4 7h8z" fill="#f2c272"/>`;});
  }
 }
 const ticks=Math.max(2,Math.floor(plotWidth/110));for(let n=0;n<=ticks;n++){const i=Math.min(visibleDays.length-1,Math.floor(n*(visibleDays.length-1)/ticks));out+=`<text x="${x(i)}" y="${height-10}" text-anchor="middle">${visibleDays[i]?.slice(5)||''}</text>`;}
 out+=`<line id="crosshair" x1="0" x2="0" y1="20" y2="${height-30}" stroke="#cedbee" stroke-dasharray="3 4" visibility="hidden"/><g id="cursorDate" visibility="hidden"><rect x="-45" y="${height-27}" width="90" height="23" rx="4" fill="#d8e8f8"/><text id="cursorDateText" y="${height-11}" text-anchor="middle" style="fill:#101d2d"></text></g></svg><div id="tooltip" class="chart-tooltip" aria-hidden="true"></div>`;$('chart').innerHTML=out;
 $('scrubber').max=Math.max(0,visibleDays.length-1);$('scrubber').value=visibleDays.length-1;hoverIndex=-1;
}
function readAt(index){index=Math.max(0,Math.min(visibleDays.length-1,index));hoverIndex=index;const d=visibleDays[index],p=asset().points.find(p=>p.date===d),b=(priceCache.get(assetId)||[]).find(p=>p.date===d),w=$('chart').clientWidth,x=46+(index+.5)*(w-90)/visibleDays.length,line=$('crosshair');if(line){line.setAttribute('x1',x);line.setAttribute('x2',x);line.setAttribute('visibility','visible');}
 const state=thresholdState(p),events=p?.thresholdEvents||[];
 $('cursorDate').setAttribute('transform',`translate(${Math.max(46,Math.min(w-46,x))},0)`);$('cursorDate').setAttribute('visibility','visible');$('cursorDateText').textContent=d;
 const priceText=b?`开 ${fmt(b.open)} · 高 ${fmt(b.high)} · 低 ${fmt(b.low)} · 收 ${fmt(b.close)}`:'当日价格缺失 / 非交易日';
 $('readout').textContent=d+' · '+(p?`${p.cycle} ${p.day}${p.unit} · 场外 ${p.otc} · 爆破 ${p.burst} · 质量 ${p.quality}`:'场外来源缺失，不补值')+' · '+priceText+(state.length?' · '+state.join(' / '):'')+(events.length?' · 当日'+events.join(' / '):'')+(locked?' · 已锁定':'');
 $('tooltip').innerHTML=`<strong>${d} ${locked?'· 已锁定':''}</strong><div>${p?esc(p.cycle+'第'+p.day+p.unit+' · '+sourceLabel(p)):'当日场外数据缺失'}</div><div class="tip-prices">${b?['open','high','low','close'].map((k,i)=>`<span>${['开','高','低','收'][i]} <b>${fmt(b[k])}</b></span>`).join(''):priceText}</div><div class="tip-indices"><span>场外 <b class="${p?.otc<1000?'tone-red':''}">${fmt(p?.otc)}</b></span><span>爆破 <b class="${p?.burst<200?'tone-amber':''}">${fmt(p?.burst)}</b></span></div>${state.map(t=>`<span class="threshold-badge ${t.startsWith('场外')?'danger':'warning'}">${t}</span>`).join('')}${events.length?'<div class="tone-amber">▼ 当日：'+esc(events.join('、'))+'</div>':''}${p?.thresholdCandidates?.length?'<div class="tone-amber">跨缺页/换源：跌破日期待核</div>':''}${p?.dataWarnings?.length?'<div class="tone-amber">有来源冲突或异常，见右侧核对项</div>':''}`;
 $('tooltip').style.left=Math.max(8,Math.min(w-292,x>w/2?x-294:x+16))+'px';$('scrubber').value=index;renderPlan(d);
}
function render(){
 const pinned=locked?visibleDays[hoverIndex]:null;
 $('priceMode').value=priceMode;
 const p=atDate(asset(),asOf),isPast=asOf<data.dataDate;$('freshness').textContent=(isPast?'历史回看 · ':'')+'最新场外来源 '+data.dataDate+'；当前日期 '+today()+'。'+(data.dataDate<today()?'最新原页缺失，所有标的仅作历史观察。':'来源日期已到今日，仍需独立价格与风险确认。')+(p?.date<asOf?' 所选日期缺页，右侧明确显示最近记录。':'');
 $('assetSelect').value=assetId;$('asOf').value=asOf;renderList();renderPlan();chartSvg();readAt(pinned&&visibleDays.includes(pinned)?visibleDays.indexOf(pinned):visibleDays.length-1);$('loadPrice').disabled=!pairMap[assetId]||priceBusy.has(assetId);$('priceStatus').textContent=priceNotes.get(assetId)||(pairMap[assetId]?'可加载 Binance '+pairMap[assetId]+' 现货日K作为对照，并非原页指定交易场所。':'该标签未配置公开价格映射；可导入你核实过的本地CSV，不猜测代码。');
}
function select(id){assetId=id;locked=false;render();}
async function loadPrice(){const id=assetId,pair=pairMap[id];if(!pair||priceBusy.has(id))return;priceBusy.add(id);priceNotes.set(id,'正在读取 Binance '+pair+' 已闭合日K…');render();try{const params=new URLSearchParams({symbol:pair,interval:'1d',startTime:String(dayTime(data.startDate)),endTime:String(dayTime(data.dataDate)+DAY-1),limit:'1000'});const res=await fetch('https://api.binance.com/api/v3/klines?'+params,{signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('公开接口不可用（'+res.status+'）');const raw=await res.json();if(!Array.isArray(raw))throw Error('接口格式异常');const bars=raw.filter(r=>r[6]<Date.now()).map(r=>({date:isoDay(r[0]),open:+r[1],high:+r[2],low:+r[3],close:+r[4]}));if(!bars.length)throw Error('所选历史区间没有可用日K');const validated=parseBars('date,open,high,low,close\n'+bars.map(b=>[b.date,b.open,b.high,b.low,b.close].join(',')).join('\n'));priceCache.set(id,validated);priceNotes.set(id,'Binance '+pair+' 现货 · UTC已闭合日K · 读取 '+new Date().toLocaleString('zh-CN')+' · 仅浏览器内存，不是交易指令');}catch(e){priceNotes.set(id,'价格缺失：'+e.message+'。场外图仍可使用；可导入本地CSV。');}finally{priceBusy.delete(id);if(id===assetId)render();}}
async function start(){try{const res=await fetch('./data/snapshot.json',{cache:'no-cache'});if(!res.ok)throw Error('快照读取失败');data=await res.json();if(data.schema!=='traderhome_otc_daily_v1'||!data.assets.length)throw Error('快照版本或内容异常');await refreshPublishedPrices(true);asOf=latestViewDate();const urlAsset=new URL(location.href).searchParams.get('asset');if(data.assets.some(a=>a.id===urlAsset))assetId=urlAsset;$('assetSelect').innerHTML=data.assets.map(a=>`<option value="${esc(a.id)}">${esc(a.id)} · ${esc(a.sector)}</option>`).join('');$('asOf').min=data.startDate;$('asOf').max=today();$('stamp').textContent=data.assets.length+'个标的 · '+data.recordCount+'条记录 · 始于 '+data.startDate;
 $('assetSelect').addEventListener('change',e=>select(e.target.value));$('assetList').addEventListener('click',e=>{const b=e.target.closest('[data-asset]');if(b)select(b.dataset.asset);});$('search').addEventListener('input',renderList);$('filter').addEventListener('change',renderList);$('asOf').addEventListener('change',e=>{if(e.target.value>=data.startDate&&e.target.value<=today()){asOf=e.target.value;locked=false;render();}});$('latestBtn').addEventListener('click',()=>{asOf=latestViewDate();locked=false;render();});document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{span=+b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));chartSvg();readAt(visibleDays.length-1);}));
 $('priceMode').addEventListener('change',e=>{priceMode=e.target.value;usePublishedPrices();render();});
 $('loadPrice').addEventListener('click',loadPrice);$('priceFile').addEventListener('change',async e=>{const file=e.target.files[0],id=assetId;if(!file)return;try{if(file.size>2e6)throw Error('文件超过2MB');const bars=parseBars(await file.text());priceCache.set(id,bars);priceMode='local';priceNotes.set(id,'用户本地CSV · 数据日 '+bars[0].date+' 至 '+bars.at(-1).date+' · 交易所与时区由你确认 · 不上传');}catch(err){priceNotes.set(id,'导入失败：'+err.message);}e.target.value='';if(id===assetId)render();});
 const pointer=e=>{const r=$('chart').getBoundingClientRect();readAt(Math.floor((e.clientX-r.left-46)/(r.width-90)*visibleDays.length));};$('chart').addEventListener('pointermove',e=>{if(!locked)pointer(e);});$('chart').addEventListener('click',e=>{locked=!locked;pointer(e);});$('chart').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();readAt((hoverIndex<0?visibleDays.length-1:hoverIndex)+(e.key==='ArrowLeft'?-1:1));}});$('scrubber').addEventListener('input',e=>readAt(+e.target.value));let resize;new ResizeObserver(()=>{clearTimeout(resize);resize=setTimeout(()=>{chartSvg();readAt(visibleDays.length-1);},80);}).observe($('chart'));render();
 setInterval(async()=>{if(document.hidden)return;const wasLatest=asOf===latestViewDate();await refreshPublishedPrices();if(wasLatest)asOf=latestViewDate();$('asOf').max=today();render();},300000);
 }catch(e){$('freshness').textContent='数据暂不可用：'+e.message+'。不提供行动结论。';$('chart').innerHTML='<p class="error">请稍后刷新。不会用示例数据替代真实历史。</p>';}}
start();
